import { z } from "zod";

// The stored shape of a cookbook extraction is the `cookbook` crate's book
// tree, serialized verbatim from Rust (see `@cubby/recipebridge`'s `Cookbook`
// and `RunReport` types, generated by tsify). These zod schemas are loose on
// purpose: they name only the fields cubby reads, pass everything else
// through, and never re-derive structure the crate already validated. The
// compile-time assignments in `apps/web/src/lib/cookbook-types.ts` keep them
// assignable from the wasm types.

// Unknown keys are kept (as JSON) rather than stripped: the stored tree must
// round-trip every field the crate wrote, not only the ones cubby reads.
const passthrough = <T extends z.ZodRawShape>(fields: T) =>
  z.object(fields).catchall(z.json());

/** An image inside the EPUB archive: a path, never a URL. */
export const archiveImageRefSchema = passthrough({
  path: z.string().min(1),
  mime: z.string().min(1),
  alt: z.string().nullable().optional(),
  caption: z.string().nullable().optional(),
  line: z.number().int().nonnegative().nullable().optional(),
});
export type ArchiveImageRef = z.infer<typeof archiveImageRefSchema>;

export const cookbookRefKind = z.enum([
  "ingredient",
  "step",
  "note",
  "variation",
  "caption",
]);
export const cookbookRefMethod = z.enum(["anchor", "page", "title"]);

/** A resolved cross-reference to another item in the same book. */
export const cookbookRecipeRefSchema = passthrough({
  target_id: z.string().min(1),
  text: z.string(),
  kind: cookbookRefKind,
  method: cookbookRefMethod,
});
export type CookbookRecipeRef = z.infer<typeof cookbookRecipeRefSchema>;

// The `ingredient` parser's structured reading, as `WIngredient` already
// crosses the wasm boundary today (snake_case `upper_value`).
export const parsedAmountSchema = passthrough({
  unit: z.string(),
  value: z.number(),
  upper_value: z.number().nullable().optional(),
});
export const parsedIngredientSchema = passthrough({
  name: z.string(),
  amounts: z.array(parsedAmountSchema),
  modifier: z.string().nullable().optional(),
  optional: z.boolean().optional(),
});

export const cookbookIngredientLineSchema = passthrough({
  raw: z.string(),
  line: z.number().int().nonnegative(),
  parsed: parsedIngredientSchema,
  confidence: z.string(),
  ref: cookbookRecipeRefSchema.nullable().optional(),
});
export type CookbookIngredientLine = z.infer<
  typeof cookbookIngredientLineSchema
>;

export const cookbookStepSchema = passthrough({
  text: z.string(),
  line: z.number().int().nonnegative(),
  refs: z.array(cookbookRecipeRefSchema).default([]),
});

export const cookbookNoteSchema = passthrough({
  label: z.string().nullable().optional(),
  text: z.string(),
  line: z.number().int().nonnegative(),
  refs: z.array(cookbookRecipeRefSchema).default([]),
});

export const cookbookSectionSchema = passthrough({
  name: z.string().nullable().optional(),
  ingredients: z.array(cookbookIngredientLineSchema),
  steps: z.array(cookbookStepSchema),
});
export type CookbookSection = z.infer<typeof cookbookSectionSchema>;

// Mirrors the Rust `recipe_types::RecipeTimes` JSON (snake_case, strings and
// minute counts carried independently — see `import-recipe.ts`).
const cookbookTimes = passthrough({
  active: z.string().nullable().optional(),
  total: z.string().nullable().optional(),
  prep: z.string().nullable().optional(),
  cook: z.string().nullable().optional(),
  active_minutes: z.number().int().nonnegative().nullable().optional(),
  total_minutes: z.number().int().nonnegative().nullable().optional(),
  prep_minutes: z.number().int().nonnegative().nullable().optional(),
  cook_minutes: z.number().int().nonnegative().nullable().optional(),
});

export const cookbookRecipeMetaSchema = passthrough({
  description: z.array(z.string()).default([]),
  recipe_yield: z.string().nullable().optional(),
  times: cookbookTimes.nullable().optional(),
  equipment: z.array(z.string()).default([]),
  category: z.string().nullable().optional(),
  page: z.string().nullable().optional(),
});

export const cookbookSpanSchema = passthrough({
  start: z.number().int().nonnegative(),
  end: z.number().int().nonnegative(),
  doc_path: z.string(),
  page: z.string().nullable().optional(),
});

/** A recipe item: the only kind cubby imports. */
export const cookbookRecipeSchema = passthrough({
  kind: z.literal("recipe"),
  id: z.string().min(1),
  title: z.string(),
  name: z.string().min(1),
  meta: cookbookRecipeMetaSchema,
  sections: z.array(cookbookSectionSchema),
  photos: z.array(archiveImageRefSchema).default([]),
  notes: z.array(cookbookNoteSchema).default([]),
  variant_of: z.string().nullable().optional(),
  span: cookbookSpanSchema,
});
export type CookbookRecipe = z.infer<typeof cookbookRecipeSchema>;

const cookbookOtherItemSchema = passthrough({
  kind: z.enum(["technique", "essay"]),
  id: z.string().min(1),
  title: z.string(),
  name: z.string().min(1),
  photos: z.array(archiveImageRefSchema).default([]),
  span: cookbookSpanSchema,
});

export const cookbookItemSchema = z.discriminatedUnion("kind", [
  cookbookRecipeSchema,
  cookbookOtherItemSchema,
]);
export type CookbookItem = z.infer<typeof cookbookItemSchema>;

export const cookbookChapterSchema = passthrough({
  id: z.string().min(1),
  title: z.string().nullable().optional(),
  items: z.array(cookbookItemSchema),
});
export type CookbookChapter = z.infer<typeof cookbookChapterSchema>;

export const cookbookEdgeSchema = passthrough({
  from: z.string().min(1),
  to: z.string().min(1),
  kind: cookbookRefKind,
  method: cookbookRefMethod,
});
export type CookbookEdge = z.infer<typeof cookbookEdgeSchema>;

export const cookbookSourceSchema = passthrough({
  label: z.string(),
  sha256: z.string(),
  title: z.string(),
  authors: z.array(z.string()).default([]),
  identifiers: z.array(z.string()).default([]),
  subjects: z.array(z.string()).default([]),
});

/** The whole book tree, as stored in `Cookbook.rawJson`. */
export const cookbookExtractionSchema = passthrough({
  contract: z.string().min(1),
  source: cookbookSourceSchema,
  cover: archiveImageRefSchema.nullable().optional(),
  chapters: z.array(cookbookChapterSchema),
  edges: z.array(cookbookEdgeSchema).default([]),
});
export type CookbookExtraction = z.infer<typeof cookbookExtractionSchema>;

/**
 * The run report stored beside the tree (`Cookbook.report`): every model
 * call, chunk, cross-check, and cost. Cubby only reads a few summary fields;
 * the rest is displayed as-is.
 */
export const cookbookRunReportSchema = passthrough({
  run_id: z.string().min(1),
  started_at: z.string(),
  finished_at: z.string(),
  total_cost_usd: z.number(),
  cost_complete: z.boolean(),
  wall_ms: z.number().int().nonnegative(),
  incomplete: z.boolean(),
  cancelled: z.boolean(),
  calls: z.array(z.record(z.string(), z.json())).default([]),
  chunks: z.array(z.record(z.string(), z.json())).default([]),
  crosscheck: passthrough({
    nav_titles: z.number().int().nonnegative(),
    matched: z.number().int().nonnegative(),
    missing: z.array(z.string()).default([]),
    phantom: z.array(z.string()).default([]),
    recall: z.number().nullable().optional(),
  }),
  usage_by_model: z
    .array(
      passthrough({
        model: z.string(),
        calls: z.number().int().nonnegative(),
        cost_usd: z.number().nullable().optional(),
      }),
    )
    .default([]),
});
export type CookbookRunReport = z.infer<typeof cookbookRunReportSchema>;

/** Every recipe item in reading order, with its chapter's title. */
export const flattenCookbookRecipes = (
  extraction: CookbookExtraction,
): Array<{ recipe: CookbookRecipe; chapter: string | null }> =>
  extraction.chapters.flatMap((chapter) =>
    chapter.items.flatMap((item) =>
      item.kind === "recipe"
        ? [{ recipe: item, chapter: chapter.title ?? null }]
        : [],
    ),
  );

/**
 * Whether a stored `rawJson` predates the book-tree format: those rows hold
 * an `ImportRecipe[]`, which the column's declared type cannot express.
 */
export const isLegacyCookbookRawJson = (stored: CookbookExtraction): boolean =>
  Array.isArray(stored);
